const q=s=>document.querySelector(s);let token=location.hash.slice(1)||sessionStorage.getItem('mizze-pc-token');history.replaceState(null,'','/pc');if(token)sessionStorage.setItem('mizze-pc-token',token);let state={fakelag:false,ghost:false,telekill:false},busy=false,selected='';
async function request(data){let r=await fetch('/api/control'+(selected?'?session='+encodeURIComponent(selected):''),{method:data?'POST':'GET',headers:{Authorization:'Bearer '+(token||''),'Content-Type':'application/json'},...(data?{body:JSON.stringify({...data,session:selected})}:{})});let v=await r.json();if(!r.ok)throw Error(v.error);return v;}
function render(v){const list=q('#client'),old=selected;list.replaceChildren();for(const c of v.clients||[]){let o=document.createElement('option');o.value=c.session;o.textContent=c.label;list.append(o);}if(![...list.options].some(x=>x.value===selected))selected=list.options[0]?.value||'';list.value=selected;if(selected!==old){poll();return;}state=v.control;for(let b of document.querySelectorAll('[data-mode]')){let on=state[b.dataset.mode];b.setAttribute('aria-pressed',on);b.textContent=on?'BẬT':'TẮT';}q('#status').textContent='Máy chủ '+(v.gateway==='ready'?'đang chạy':'đã dừng')+' · phiên bản lệnh '+v.revision;q('#metrics').textContent='↑ '+(v.stats.up/1024).toFixed(1)+' KB  /  ↓ '+(v.stats.down/1024).toFixed(1)+' KB\nHàng đợi: '+v.stats.queued+' byte · Bỏ do đầy: '+v.stats.dropped+' · Gói giữ: '+(v.stats.heldPackets||0)+' · Đang xả: '+(v.stats.flushingPackets||0)+' · Phiên web: '+v.sessions;let m=v.stats.matching||{},c=v.stats.captured||{};q('#diagnostic').textContent='Gói khớp bộ lọc / đã giữ: FakeLag '+(m.fakelag||0)+' / '+(c.fakelag||0)+' · Ghost '+(m.ghost||0)+' / '+(c.ghost||0)+' · Telekill '+(m.telekill||0)+' / '+(c.telekill||0)+'. '+(!v.stats.udpIn&&!v.stats.udpOut?'Chưa thấy UDP đi qua gateway.':!v.stats.lastGameAt?'Có UDP, nhưng chưa khớp bộ lọc Hi.py.':'Đã bắt được gói khớp bộ lọc.');q('#ports').textContent='UDP đang thấy (cổng: ra/về): '+Object.entries(v.stats.ports||{}).sort((a,b)=>b[1].at-a[1].at).slice(0,12).map(([port,x])=>port+': '+x.up+'/'+x.down).join(' · ');}
async function set(next){if(busy||!selected)return;busy=true;document.querySelectorAll('button').forEach(b=>b.disabled=true);try{render(await request(next));}catch(e){q('#status').textContent=e.message;}finally{busy=false;document.querySelectorAll('button').forEach(b=>b.disabled=false);}}
for(let b of document.querySelectorAll('[data-mode]'))b.onclick=()=>set({...state,[b.dataset.mode]:!state[b.dataset.mode]});q('#off').onclick=()=>set({fakelag:false,ghost:false,telekill:false});
async function poll(){if(!busy)try{render(await request())}catch(e){q('#status').textContent=e.message+' Mở bằng shortcut MỞ BẢNG PC.';}}
q('#client').onchange=()=>{selected=q('#client').value;poll();};poll();setInterval(poll,2000);fetch('/api/info').then(r=>r.json()).then(v=>{let e=q('#urls');for(let url of [...(v.publicOrigin?[v.publicOrigin]:[]),...v.localUrls]){let a=document.createElement('a');a.href=url;a.textContent=url;a.style.display='block';e.append(a);}});
